#include <linux/tracepoint.h>
#include <linux/limits.h>

void handle_syscall_entry(void* ignore, struct pt_regs* regs, long id) {
    unsigned int syscall_num = (unsigned int)id;
    struct syscall_metadata* metadata = get_syscall_metadata(syscall_num);

    if (!metadata || !metadata->enabled)
        return;

    size_t size = sizeof(struct syscall_trace) + metadata->arg_count * sizeof(struct syscall_arg);
    size = ALIGN(size, 8);

    struct syscall_trace* record = kmalloc(size, GFP_KERNEL);
    if (!record)
        return;

    record->syscall_num = syscall_num;
    record->arg_count = metadata->arg_count;

    for (unsigned int i = 0; i < metadata->arg_count; i++) {
        struct syscall_arg* arg = &record->args[i];
        arg->name = metadata->arg_names[i];
        arg->value = get_register_value(regs, metadata->arg_regs[i]);
    }

    tracepoint_submit(record, size);

    kfree(record);
}
